quests[35637] = { id = 35637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Steinzornklippen" }
quests[35638] = { id = 35638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Jedes bisschen hilft." }
quests[35639] = { id = 35639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine MENGE Artefaktfragmente", progress = "So viel Ihr tragen könnt.", completion = "Hervorragende Arbeit, {class}! Ich werde Verteidiger Maraad von Eurer Tapferkeit berichten." }
quests[35640] = { id = 35640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Gefallenen", description = "Ich... habe es fast geschafft. Die... meisten von uns sind... tot. Die anderen sind... nicht mehr sie selbst.\n\nDiese taumelnden Sporenbestien... sind die Ursache... ziehen uns weiter in den Sumpf. Ihr müsst... sie aufhalten.", sourceObjective = "Tötet 7 Fungusschlinger.", completion = "Danke, dass Ihr meine gefallenen Freunde gerächt habt. Wir werden dieser Sache auf den Grund gehen, das schwöre ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[35641] = { id = 35641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Steinzornklippen" }
quests[35642] = { id = 35642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöse Kapsel", description = "Diese Kapsel ähnelt denen, die auf oder bei den Körpern hier in der Gegend wachsen, allerdings pulsiert sie seltsam.\n\nKhaano dürfte sich dafür interessieren.", sourceObjective = "Bringt die leuchtende rote Kapsel zu Khaano im Blutroten Sumpf in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ich habe sie schon an Leichen und den Bestien gesehen, aber noch nie so groß. Lasst mich mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[35643] = { id = 35643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 062 – Bergsteigerrucksack" }
quests[35644] = { id = 35644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade für die Lebenden", description = "Wie Ihr seht, waren die Toten die Glücklichen. Die Lebenden streifen umher und greifen alle an, die nicht mit diesen abscheulichen Sporen infiziert sind.\n\nIch bringe es nicht übers Herz, sie zu töten, aber wenn Ihr diesen armen Seelen Gnade widerfahren lassen könntet, wäre ich Euch sehr dankbar.", sourceObjective = "Tötet 6 pilzbedeckte Schlurfer.", completion = "Vielleicht hätten wir mit ihnen keine Zeit verschwenden sollen. Dieser Ort... betrübt mich. Trotzdem habt Ihr eine gute Tat vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[35645] = { id = 35645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Fungus", description = "Ich sehe langsam eine starke... Verbindung... zwischen dem Pilz und den Kreaturen, die in ihm leben. Bestimmte Pilze sind stärker als andere.\n\nWenn ich ein paar Proben hätte, könnte ich damit die Quelle dieses abscheulichen Pilzes aufspüren... und das Problem beseitigen.", sourceObjective = "Sammelt 5 leuchtende Pilze ein.", progress = "Wo bleiben meine Pilze?", completion = "Leider gewöhne ich mich so sehr an den Geruch dieser Sporen, dass ich ihn mittlerweile sogar als angenehm empfinde. Wenn ich hiervon etwas esse, geht unsere Arbeit vielleicht schneller voran...", sourceObjectiveStatus = "unverified-source-field" }
quests[35646] = { id = 35646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 006 - Dampfdruckvorräte" }
quests[35647] = { id = 35647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Ernte", description = "Tiefer im Sumpf wird der Sporenwuchs immer dichter, aber diese größeren Pilzbestien sind der Schlüssel.\n\nJa, tötet sie und holt Euch ihre Sporenkapseln. Ich brauche sie, um meine... Nachforschungen voranzutreiben.", sourceObjective = "Bringt Khaano 3 Sporenkapseln von den Fungusstampfern.", progress = "Diese Kapseln sind von kritischer Bedeutung, {name}, ich brauche sie!", completion = "Ich... Ich muss sie wie die Pilze verschlingen. Es wird mir helfen, die Quelle zu finden, ich schwöre!", sourceObjectiveStatus = "unverified-source-field" }
quests[35648] = { id = 35648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 005 – Dampfdruckvorräte" }
quests[35649] = { id = 35649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Windende Morast" }
quests[35650] = { id = 35650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel III: Ritual der Verkohlten", description = "Ich habe ein seltsames Ritual der Urtume beobachten können. Sie treten in ein Feuer, brennen sich die Blätter von ihren Ästen und verkohlen so ihre Rinde.\n\nIch nenne es das \"Ritual der Verkohlten\". Wenn wir die Urtume schwächen wollen, können wir sie loswerden, bevor sie noch stärker werden.\n\n- Frenna", sourceObjective = "Tötet 4 Urtume.", completion = "Diese Urtume sind verrückt! Kaum zu glauben, dass sie sich die eigenen Blätter abbrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35651] = { id = 35651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel II: Die Ernte", description = "Ich habe eine Kreatur gesehen, die mit den Schösslingen der Urtume arbeitet. Sie erfüllt sie mit Zorn und Hass gegen alle Kreaturen, die nicht wie sie sind.\n\nVielleicht ist dieser Botani ja für das ungewöhnlich aggressive Verhalten der Urtume hier im Schlingenherz verantwortlich.\n\nOb es uns wohl weiterhelfen würde, diesen Botani zu töten? Allein wäre ich dieser Kreatur jedenfalls nicht gewachsen.\n\n- Frenna", sourceObjective = "Tötet Ontogen den Ernter.", completion = "Ihr habt also das fiese Riesenmonster erledigt? Ihr macht hier draußen ja mächtig Ärger!", sourceObjectiveStatus = "unverified-source-field" }
quests[35652] = { id = 35652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holzanbau", description = "Das Sägewerk ist fast fertig, aber wir brauchen mehr Holz!\n\nDie Rangari haben mir gesagt, dass die Botani die Urtume mit einer Art Dünger blitzschnell aus dem Boden schießen lassen können.\n\nHolt mir was von dem Zeug, dann sprießen hier die Bäume wie der dickste Zwergenbart.\n\nWas? Oh, Glyza? Sie ist hier abgestürzt und ich hab sie gefunden. Sie kennt sich ganz gut mit der Holzfällerei aus. Ich werde sie später zurück zum Außenposten bringen.\n\nWir treffen uns dann im Schlingenherz, wenn ich das finden kann.", sourceObjective = "Beschafft 100 Wachstumssaft für Urtume von Botani oder Urtumen.", progress = "Glyza kann gut mit Werkzeugen umgehen.", completion = "Zu klein gewachsen? Ich? Wer hat das gesagt?! Oh...", sourceObjectiveStatus = "unverified-source-field" }
quests[35654] = { id = 35654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel I: Nahrung anpflanzen", description = "Im Schlingenherz gibt es seltsam schimmernde Objekte, die offensichtlich von einer Art stechenden Kreatur befruchtet werden.\n\nDie Botani sammeln manchmal ein, was auch immer diese Kapseln produzieren. Ich weiß nicht genau, worum es sich da handelt, aber es könnte gefährlich für uns sein.\n\n- Frenna", sourceObjective = "Zerstört 8 Sporenkapseln.", completion = "Keine Ahnung, wozu diese Sporen gedient haben... Aber mir ist es lieber, dass es sie nicht mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35656] = { id = 35656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine beherzte Suche", sourceObjective = "Untersucht die mysteriöse Präsenz im Blutroten Sumpf.", completion = "Das ist bedauernswert... Ich hatte gehofft... Nun, wir sind dennoch auf der richtigen Spur und unserem Ziel einen Schritt näher.\n\n... Und keinen Schritt zu früh – diese schreienden Bestien gehen mir wirklich auf die Nerven...", sourceObjectiveStatus = "unverified-source-field" }
quests[35659] = { id = 35659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Sumpfs", description = "Das Hämmern in meinem Kopf ist beinahe unerträglich, aber ich muss das durchziehen. Ich weiß, wo ich mit all den Sporenproben, die ich gesammelt habe, hingehen muss und was ich damit machen muss.\n\nIch werde die Quelle finden und verstreue dort... nein! Zerstören werde ich sie! Ich werde tun, was getan werden muss!", sourceObjective = "Dringt mit Khaano tiefer in den Blutroten Sumpf ein und kümmert Euch um das, was Ihr vorfindet.", completion = "Das sind furchtbare Neuigkeiten. Ich werde alle Späher anweisen, sich von nun an vom Blutroten Sumpf fernzuhalten. Danke. Ich bin froh, dass Euch die Sporen nichts anhaben konnten...", sourceObjectiveStatus = "unverified-source-field" }
quests[35660] = { id = 35660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 052 – Pilzüberzogene Truhe" }
quests[35661] = { id = 35661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 054 – Traumblume" }
quests[35662] = { id = 35662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 053 – Dampfdruckvorräte" }
quests[35663] = { id = 35663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Teamwork", description = "Eine der wichtigsten Fähigkeiten, die Archäologen mitbringen müssen, ist gute Zusammenarbeit. Der Schlüssel dazu liegt darin, zu wissen, wann man geben und wann man nehmen muss.\n\nDie Oger von Hochfels graben in der Schlucht mysteriöse Artefakte aus. Ich möchte, dass Ihr im Namen der Archäologie mit den Ogern von Hochfels zusammenarbeitet!\n\nWie ich bereits sagte: Es geht ums Geben und Nehmen. Die Oger haben gegeben, indem sie die Artefakte durch harte Arbeit ausgegraben haben. Nun möchte ich, dass Ihr ihnen diese Artefakte abnehmt und sie hierher bringt!\n\nEin perfektes Beispiel für gute Zusammenarbeit!", sourceObjective = "Beschafft 10 mysteriöse Artefakte.", progress = "Habt Ihr die mysteriösen Artefakte beschafft? Ihr wisst ja, gute Zusammenarbeit ist alles!", completion = "Gute Arbeit, Kleiner!\n\nIch hoffe, Ihr habt heute etwas über Teamwork gelernt. Hier habt Ihr Euren Anteil, abzüglich der Unterrichtsgebühr... des Bearbeitungszuschlags der Werterhaltungsgesellschaft des Dampfdruckkartells... und natürlich eines kleinen Trinkgelds!", sourceObjectiveStatus = "unverified-source-field" }
quests[35664] = { id = 35664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten für Saatbringer", description = "Wenn diese Saatbringer getötet werden, überleben ihre Samen. Daraus entspringen neue Saatbringer, und zwar nicht im Laufe der Jahre, sondern innerhalb weniger Stunden.\n\nIhre Überreste hierzulassen, würde in kürzester Zeit dazu führen, dass der Außenposten überrannt wird.\n\nWir haben gelernt, dass wir das verhindern können, indem wir die Überreste verbrennen.", sourceObjective = "Verbrennt 5 Leichen von Saatbringerurtumen.", completion = "Die Urtume sollten vorerst keine Gefahr mehr für Euren Außenposten darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35665] = { id = 35665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben Gesellschaft", description = "Kommandant, ich habe ganz in der Nähe Soldaten der Eisernen Horde entdeckt.\n\nSelbst für sie ist es ganz schön frech, sich in solch ein tödliches Gebiet vorzuwagen.\n\nWenn wir uns nicht ihrer Gegenwart annehmen, werden sie sicherlich zur Bedrohung für Euer Lager.\n\nDarf ich um Eure Hilfe bei der Untersuchung des feindlichen Lagers bitten, während ich mich noch tiefer in den Schluchten umsehe?", sourceObjective = "Erkundet das Lager der Eisernen Horde im Schwefelbecken.", completion = "Ich danke Euch. Ich stehe in Eurer Schuld.\n\nDiese überhebliche Eiserne Horde hat sich heute einen gefährlichen Feind gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[35666] = { id = 35666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rangari in Rot", description = "Gorgrond ist ein sehr gefährlicher Ort. Ich habe Spähertrupps losgeschickt, um die verschiedenen Regionen auszukundschaften.\n\nEiner der Trupps untersucht ein Gebiet, das wir den Blutroten Sumpf nennen. Aber diese Einheit ist bis jetzt nicht zurückgekehrt. Ich möchte, dass Ihr sie findet und mir falls möglich einen Bericht beschafft.", sourceObjective = "Findet Khaano in der Nähe des Blutroten Sumpfes in Gorgrond.", completion = "D'kaan schickt Euch? Mein Bericht wird ihm ganz und gar nicht gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35667] = { id = 35667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädelsammler im Blutroten Sumpf", description = "Grulkor und seine Einheit sind oft wochenlang unterwegs. Sie kehren meist nur zurück, wenn sie keine weiteren Trophäen und Vorräte schleppen können. Aber jetzt ist er schon viel zu lang fort.\n\nEr erwähnte, dass er zum ersten Mal in einem Gebiet auf Jagd gehen wollte, das man den Blutroten Sumpf nennt. Schaut bitte nach, ob er noch am Leben ist.", sourceObjective = "Findet Grulkor in der Nähe des Blutroten Sumpfes in Gorgrond.", completion = "Medulla schickt Euch also? Nun, wir gehen erst, wenn ich hier fertig bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[35668] = { id = 35668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syths Geheimnis", description = "Unser verstorbener Freund hier hat mehr versteckt als ein paar alte Schriftrollen und erotische Zauberer-Romane. Er besaß etwas wirklich Wertvolles.\n\nEr behauptet, wenn ich seine Notizen richtig verstehe, das Auge von Anzu gefunden zu haben – Terokks Seherkugel in den Tagen nach seinem Niedergang.\n\nWir brauchen diese Kugel! Seinen Aufzeichnungen zufolge hat er sie in einem Verheererunterschlupf weiter oben an der Straße versteckt.", sourceObjective = "Beschafft das Auge von Anzu.", progress = "Was für ein Schatz! Ich frage mich, ob diese Sonnenklaue sich dessen Bedeutung bewusst war?", completion = "<Reshad blickt in die tiefschwarze Kugel.>\n\nErstaunlich. Es scheint unfassbar, dass Terokk über diese Kugel mit Anzu kommuniziert hat. Mit solch einem Werkzeug könnte man zu einem formidablen Dunkelwirker werden.\n\nKommt, lasst uns die Kugel sicher ins Versteck bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35669] = { id = 35669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Keehos abgetrennte Pfote", description = "Von: Zuchtmeister Gornek\n\nKeeho der Saberon stellt eine ernsthafte Gefahr für Axtfall dar.\n\nEr hat sich angewöhnt, Peons der Nachtschicht zu jagen und ihre Leichname in seinen Bau im Rudelterritorium zu verschleppen.\n\nJeder, der mir seine abgetrennte Pfote als Beweis seines Ablebens bringen kann, wird eine große Belohnung erhalten.", sourceObjective = "Besorgt Keehos abgetrennte Pfote von Keeho dem Wilden.", progress = "Lok'tar, Kommandant.", completion = "Die Peons werden von Eurem Ruhm singen, Kommandant. Lok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[35670] = { id = 35670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Rückenschlitzers Panzer", description = "Von: Killga\n\nIch werde jeden reich belohnen, der mir Rückenschlitzers Panzer bringt.\n\nIch möchte eine hochwertige Verheererausrüstung herstellen, aber ein solches Untier kann ich nicht selbst töten.\n\nReißt aber nicht zu viele Löcher rein.", sourceObjective = "Besorgt Rückenschlitzers Panzer.", progress = "Es ist eine Ehre, Euch in meiner Werkstatt begrüßen zu dürfen, Kommandant.", completion = "Ich bin froh, dass wir auf Euch zählen können, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35671] = { id = 35671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zusammentreffen der Schatten", description = "Das Terokkversteck liegt vor uns.\n\nIch hoffe, die anderen sind sicher angekommen.", sourceObjective = "Betretet das Terokkversteck mit Reshad.", completion = "Wir stehen tief in Eurer Schuld, denn Ihr habt Reshad sicher hergebracht, {name}.\n\nAllerdings hat unser Kampf gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35672] = { id = 35672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Giftstachel", description = "Von: Hutou Federwind\n\nGiftstachel ist im Himmel über Arak gefürchtet, und das sogar von den Hocharakkoa.\n\nDie Bestie hat unseren Reitern das Fliegen erschwert und wichtige Vorräte kommen nicht mehr in Axtfall an.\n\nIhr müsst nicht beweisen, dass sie tot ist. Stellt einfach sicher, das wir ihr Kreischen in den Spitzen nie mehr hören müssen.\n\nSie nistet beim Heulenden Fels im Nordosten.", sourceObjective = "Tötet Giftstachel.", completion = "Tausend Dank, Kommandant. Ich werde sofort um Nachschublieferungen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35673] = { id = 35673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Schatz 014 – Requirierte Vorräte des Kriegshymnenklans" }
quests[35674] = { id = 35674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Keehos abgetrennte Pfote", description = "Von: Leutnant Willem\n\nKeeho, ein riesiger Saberon, hat begonnen, nachts Südhafen zu überfallen. Wir verlieren andauernd Männer.\n\nIch setze ein Kopfgeld auf Keeho aus und werde jeden reich belohnen, der mir seine abgetrennte Pfote bringt.", sourceObjective = "Besorgt Keehos abgetrennte Pfote von Keeho dem Wilden.", progress = "Schön, Euch zu sehen, mein Herr.", completion = "Gut gemacht, Kommandant. Für die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[35675] = { id = 35675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Rückenschlitzers Panzer", description = "Von: Rüstmeisterin Jolie\n\nWir haben bald nicht mehr genug Material, um die Rüstung unserer Truppen zu reparieren.\n\nIch verspreche jedem eine ordentliche Belohnung, der mir den Panzer des mächtigen Verheerers Rückenschlitzer bringt. Mit dem Panzer könnten wir wochenlang unserer Rüstungen reparieren.", sourceObjective = "Besorgt Rückenschlitzers Panzer.", progress = "Oh, Kommandant! Was für eine Ehre!\n\nWie kann ich Euch helfen?", completion = "Ich hätte nie gedacht, dass jemand diese Bestie töten könnte. Vielen Dank, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[35676] = { id = 35676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Giftstachel", description = "Von: Falrogh\n\nGiftstachel verhöhnt mich jeden Tag. Die Bestie kreischt und verdirbt mir komplett die Laune.\n\nBitte, es erbarme sich doch einer und töte das Vieh. Ich brauche keine Beweise, ich will nur Ruhe.", sourceObjective = "Tötet Giftstachel.", completion = "Bei Muradinsch Bart... Ihr habt die Beschtie tatschächlich erledigt. Ein Hoch auf Euch, Kommandant... hicks!", sourceObjectiveStatus = "unverified-source-field" }
quests[35677] = { id = 35677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Versunkenes Fischerboot" }
quests[35678] = { id = 35678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 015 - Warsong Lockbox" }
quests[35679] = { id = 35679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Fall von Shattrath", description = "Grüße, {name}. Ich überbringe Euch eine weitere Nachricht von Erzmagier Khadgar.\n\nWir können nicht mehr über Socrethars Einfluss in Shattrath hinwegsehen. Er verbreitet einen gefährlichen Glauben und bekehrt jeden Tag mehr Draenei zu seiner \"neuen Ordnung\".\n\nWir müssen uns ihm endlich stellen.\n\nExarch Maladaar sollte Euch an der Spitze des Lichts in Talador erwarten. Viel Glück, {name}.", sourceObjective = "Sprecht mit Exarch Maladaar an der Spitze des Lichts in Talador.", completion = "Ich freue mich, Euch zu sehen, {name}. Eure Hilfe ist in dieser brisanten Lage von unschätzbarem Wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[35680] = { id = 35680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Fall von Shattrath", description = "Grüße, {name}. Ich überbringe Euch eine weitere Nachricht von Erzmagier Khadgar.\n\nWir können nicht mehr über Socrethars Einfluss in Shattrath hinwegsehen. Er verbreitet einen gefährlichen Glauben und bekehrt jeden Tag mehr Draenei zu seiner \"neuen Ordnung\".\n\nWir müssen uns ihm endlich stellen.\n\nLady Liadrin sollte Euch an der Spitze des Lichts in Talador erwarten. Viel Glück, {name}.", sourceObjective = "Sprecht mit Lady Liadrin an der Spitze des Lichts in Talador.", completion = "Ich freue mich, Euch zu sehen, {name}. Eure Hilfe ist in dieser brisanten Lage von unschätzbarem Wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[35682] = { id = 35682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 016 - Warsong Spear" }
quests[35683] = { id = 35683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Stadt", description = "Die Offensive in Shattrath läuft gut, aber Socrethar zeigt sich nicht.\n\nWir haben alles versucht, aber es ist uns nicht gelungen, in die innere Stadt vorzudringen. Die Verteidigungsanlangen sind einfach zu stark.\n\nAllerdings glauben wir, dass wir Socrethar hervorlocken können. Besiegt seine Leutnants und Krieger und nehmt ihre Abzeichen.\n\nWenn wir ihm diese Beweise ihrer Niederlagen zeigen, wird ihn bestimmt sein Stolz zwingen, sich uns zu stellen.", sourceObjective = "Sammelt 100 Insignien der Sargerei.", progress = "Ich stelle Euch vor keine leichte Aufgabe, denn seine Abkömmlinge sind nicht zu unterschätzen. Wie läuft die Offensive?", completion = "Hervorragend. Diese Insignien werden Socrethar bestimmt aus seinem Versteck locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35684] = { id = 35684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Stadt", description = "Die Offensive in Shattrath läuft gut, aber Socrethar zeigt sich nicht.\n\nWir haben alles versucht, aber es ist uns nicht gelungen, in die innere Stadt vorzudringen. Dort hält er sich nämlich auf.\n\nAllerdings glauben wir, dass wir Socrethar hervorlocken können. Besiegt seine Leutnants und Krieger und nehmt ihre Abzeichen.\n\nWenn wir ihm diese Beweise ihrer Niederlagen zeigen, wird ihn bestimmt sein Stolz zwingen, sich uns zu stellen.", sourceObjective = "Sammelt 100 Insignien der Sargerei.", progress = "Ich stelle Euch vor keine leichte Aufgabe, denn seine Anhänger sind nicht zu unterschätzen. Wie läuft die Offensive?", completion = "Hervorragend. Diese Insignien werden Socrethar bestimmt aus seinem Versteck locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[35685] = { id = 35685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethars Untergang", description = "Trefft mich am Eingang der Kuppel von Shattrath.\n\nDort werden wir den Anführer der Sargerei herausfordern. Wenn er darauf eingeht, wird er dort fallen.\n\nDie Kreatur, die sich Socrethar nennt, war einst mein Bruder. Ich kann nur hoffen, dass er noch etwas Licht in sich trägt.", sourceObjective = "Tötet Socrethar.", completion = "Endlich ist es getan. Othaar... mein alter Freund... ruhe in Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35686] = { id = 35686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wut und Weisheit", description = "Ein endloser Krieg tobt zwischen den Kreaturen der östlichen Wildnis und den Tieren der westlichen Einöde.\n\nSollte eine Seite die andere überwältigen, würde ganz Draenor in die Hände des Siegers fallen.\n\nIch habe die Rangari Erdanii ins Herz des Kampfs zwischen diesen beiden Mächten entsandt. Wahrscheinlich wird sie Eure Hilfe benötigen, Kommandant.", sourceObjective = "Sprecht mit Rangari Erdanii am Leidensgrat.", completion = "Diese Kreaturen sind unerbittlich in ihren Angriffen gegeneinander.", sourceObjectiveStatus = "unverified-source-field" }
quests[35687] = { id = 35687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethars Untergang", description = "Trefft mich am Eingang der Kuppel von Shattrath.\n\nDort werden wir den Anführer der Sargerei herausfordern. Wenn er darauf eingeht, wird das sein Ende sein.\n\nIch muss gestehen, dass ich mich darauf freue, {name}.", sourceObjective = "Tötet Socrethar.", completion = "Es ist endlich getan. Diese Kreatur der Finsternis wird uns nicht länger heimsuchen. Ihr Schatten liegt nicht mehr über Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[35688] = { id = 35688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Enavra Varandi" }
quests[35689] = { id = 35689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente" }
quests[35690] = { id = 35690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Artefaktfragmente" }
quests[35691] = { id = 35691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine MENGE Artefaktfragmente" }
quests[35692] = { id = 35692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 010 - Freshwater Clam" }
quests[35693] = { id = 35693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine harsche Mahnung", description = "Willkommen an der Front, Kommandant, wo die Wildnis und der Dschungel aufeinandertreffen.\n\nDer Kampf da unten tobt weiter, aber ich glaube, dass eine Seite die andere allmählich überwältigt. Das darf keinesfalls geschehen.\n\nDie Gronnlinge bekommen die Oberhand und müssen aufgehalten werden, bevor sie zur Bedrohung für Hochpass werden.\n\nIch werde mich dem Kampfgebiet nähern, während Ihr ihre Zahl dezimiert. Wir treffen uns am Leidensgrat, wenn Ihr fertig seid.", sourceObjective = "Tötet 8 Bewohner der Einöde am Leidensgrat.", completion = "Ihr seid wirklich ein talentierter Kämpfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[35694] = { id = 35694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 011 - Golden Kaliri Egg - TSH" }
quests[35695] = { id = 35695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 022 - Warsong Cache" }
quests[35696] = { id = 35696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 048 - Burning Blade Cache" }
quests[35697] = { id = 35697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friedensangebot", description = "Wir brauchen Verbündete, und zwar schnell. Kommandant, ich glaube, es wäre klug, wenn Ihr Euch Hilfe suchen würdet.\n\nSüdöstlich von hier lebt ein einsamer, ausgestoßener Arakkoa in der Nähe eines Verheerernestes. Die Verheerer lassen ihn in Ruhe, vermutlich weil er über Informationen verfügt, wie er sich vor ihnen schützen kann. Diese Informationen könnten wir gut brauchen.\n\nHier, nehmt unsere letzte Kiste mit Kaktusapfel Surprise! Das ist unsere beste Chance, Kommandant.", sourceObjective = "Bringt die Kiste mit Kaktusapfel Surprise zum Dämmerungsweisen Irizzar in den Spitzen von Arak.", completion = "Ich glaube, wir könnten zu einer Übereinkunft gelangen, Retter von Skettis. Aber zuerst...", sourceObjectiveStatus = "unverified-source-field" }
quests[35699] = { id = 35699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friedensangebot", description = "Ein Handelspartner wäre für uns von großem Nutzen, Kommandant.\n\nNordöstlich von hier lebt ein ausgestoßener Arakkoa inmitten eines Verheerernestes. Glaubt Ihr, er würde sich mit uns verbünden? Er muss ein Geheimnis haben, das ihm die Verheerer vom Leib hält.\n\nIch habe noch eine letzte Kiste Nordhainport. Vielleicht überzeugt sie ihn von unseren guten Absichten.", sourceObjective = "Bringt die Kiste mit Nordhainport zum Dämmerungsweisen Irizzar.", completion = "Ich glaube, wir könnten zu einer Übereinkunft gelangen, Retter von Skettis. Aber zuerst...", sourceObjectiveStatus = "unverified-source-field" }
quests[35701] = { id = 35701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 1" }
quests[35702] = { id = 35702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiserne Ketten", description = "Das Artefakt, das wir suchen, ist zum Greifen nah.\n\nBereitet Euch auf einen Kampf vor. Falls sie tatsächlich gelernt haben, wie man Gronn kontrolliert, könnte es heikler werden, als ich erwartet hatte.\n\nIch werde Euch in diesem Kampf beistehen, sobald Ihr angekommen seid.", sourceObjective = "Besiegt Hauptmann Brak und findet das Herz des Magnarons.", progress = "Wir haben das Artefakt. Und mit seiner Hilfe werden wir die Eiserne Horde büßen lassen.", completion = "Ja... denkt nur an die Orcs, die dank dieser Macht vor uns fallen werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[35703] = { id = 35703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure Barrier 1" }
quests[35704] = { id = 35704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wege des Ruhms", description = "Die Akolythen der Rabensprecher wurden mit Apexissteuerungen ausgerüstet. Sie müssen nur noch nahe genug herankommen.\n\nKommt, schwingen wir uns auf in den Himmel und sichern die Morgenterrasse.\n\nSobald alles auf Position ist, können wir die falschen Sonnen gegeneinander wenden, dann werden die Spitzen in Flammen aufgehen!\n\nIch freue mich schon darauf, Eure Taten für die Nachwelt festzuhalten.", sourceObjective = "Fliegt auf Ka'alu und tötet 80 Jünger.", completion = "Percy und ich würden Euch gern ein kleines Zeichen unserer Dankbarkeit überreichen. Es ist nicht viel, aber bitte, nehmt Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[35705] = { id = 35705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnäppchenjäger", description = "Kommandant, zwei Goblinschmugglerinnen – Mixxy und Trixxy Lötbrand – sind vor Kurzem auf dem Weg zum Sumpf im Osten hier vorbeigekommen.\n\nSie hatten Bohrausrüstung dabei, aber keine Waffen.\n\nDie haben garantiert Materialien, die wir brauchen, und würden sich im Gegenzug sicher über Begleitschutz freuen.\n\nEs wäre bestimmt nicht verkehrt, ihnen einen Besuch abzustatten, Kommandant.", sourceObjective = "Sprecht mit Mixxy Lötbrand im Trübsumpf.", completion = "Keine Ahnung, was Ihr so weit hier draußen wollt, aber würdet Ihr 'nem Mädchen 'nen Gefallen tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[35706] = { id = 35706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klebrige Angelegenheit", description = "Wir haben Batterien zur Ausgrabungsstätte transportiert und ich hab' mit meinem verdammten Wagen einen Unfall gebaut!\n\nMeine Schwester hat sich nicht mal umgedreht. Ich hab' die Kurve etwas schnell genommen, na und? Kann passieren!\n\nJedenfalls sind die Batterien durch die Gegend geflogen und ich bin nicht in der Lage, sie herauszuholen.\n\nAlso was sagt Ihr? Wollt Ihr mir helfen?", sourceObjective = "Bergt 5 versunkene Batterien.", progress = "Habt Ihr die Batterien?", completion = "Ihr seid wirklich ein Schatz. Hauen wir von hier ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[35707] = { id = 35707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingenherz", description = "Hallo, <Hübscher/Hübsche>. Das Sägewerk ist fertig, aber jetzt müssen wir eine Möglichkeit finden, da draußen schleunigst Holz zu fällen.\n\nDer Lachende Schädel erwähnte einen Ort namens Schlingenherz, wo die Botani alles blitzschnell aus dem Boden schießen lassen.\n\nIch bin gerade auf dem Weg dorthin.", sourceObjective = "Sprecht mit Penny Kloppertopp außerhalb des Schlingenherzens.", completion = "Heh! Seht mal, was ich hier gefunden habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[35708] = { id = 35708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingenherz", description = "Die Rangari sind schon ein Weilchen hier. Und sie haben vom Lachenden Schädel von einem Ort namens Schlingenherz erfahren.\n\nEin paar richtig böse Urtume scheinen von dort zu kommen, und die Botani verwenden eine Art Flüssigdünger, um sie schnell heranzuzüchten.\n\nIch glaube, den könnten wir auch für Euren Außenposten gebrauchen. Holz ist schließlich Holz, oder?\n\nWir treffen uns dann dort!", sourceObjective = "Sprecht mit Glirin außerhalb des Schlingenherzens.", completion = "Hey! Ich hab diesen Goblin hier beim Herumschleichen erwischt. Ich glaube, ich behalte sie. Sie sagt, sie kennt sich beim Holzfällen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[35709] = { id = 35709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schatz des Lachenden Schädels 1" }
quests[35711] = { id = 35711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 059 - Abu'gar's Tenacity" }
quests[35712] = { id = 35712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss 012 – Rotklaue der Wilde" }
quests[35713] = { id = 35713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tüftelzink-Zwillinge", description = "Kommandant, zwei Gnomschmuggler sind hier vorbeigekommen, während Ihr unterwegs wart: Filbert und Dilbert Tüftelzink. Sie gingen in Richtung des Sumpfs im Osten.\n\nSie hatten jede Menge Bohrausrüstung dabei, aber keine Waffen.\n\nWas haltet Ihr davon, ihnen im Tausch gegen einige ihrer Materialien Geleitschutz anzubieten?\n\nIch schreibe Euch auf, wohin sie unterwegs waren, solltet Ihr ihnen nacheilen wollen.", sourceObjective = "Sprecht mit Filbert Tüftelzink im Trübsumpf.", completion = "Ihr seid ja bis an die Zähne bewaffnet! Wäret Ihr interessiert daran, einem armen Gnom auszuhelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[35714] = { id = 35714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss 001 – Großfeder" }
quests[35715] = { id = 35715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss 002 – Gar'lua die Wolfsmutter" }
quests[35716] = { id = 35716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klebrige Angelegenheit", description = "Eine Schwadron Arakkoa hat uns auf dem Weg zur Ausgrabungsstätte entdeckt und unsere Karawane zerstört. Mein Bruder konnte in dem Chaos entkommen.\n\nWas hat dieser Tüftlersohn für ein Glück!\n\nIch kann unsere Bohrerbatterien nicht zurücklassen, aber sie sind in den Sumpf gefallen und ich kriege sie nicht heraus.\n\nKönntet Ihr sie vielleicht holen?", sourceObjective = "Bergt 5 versunkene Batterien.", progress = "Habt Ihr es geschafft?", completion = "Ihr rettet mir das Leben! Bringen wir sie zur Ausgrabungsstätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[35717] = { id = 35717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss 015 – Knorrhuf der Tollwütige" }
quests[35718] = { id = 35718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ein Neues", description = "Ihr rettet mir wirklich das Leben.\n\nGeht doch vor zur Ausgrabungsstätte und sagt meiner Schwester, dass ich unterwegs bin. Ich packe alles fein säuberlich zusammen und besorge einen neuen Wagen, um das Zeug rüberzuschaffen.", sourceObjective = "Sprecht mit Trixxy Lötbrand im Zekkversteck.", completion = "Oh, Mixxy schickt Euch? Was für eine Erleichterung. Ich bin nicht mal bewaffnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[35719] = { id = 35719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ein Neues", description = "Mit den Batterien aus dem Sumpf kann ich über Funk weitere Kopter anfordern und zum Lager bringen.\n\nIch bleibe hier, bis sie da sind, aber Ihr solltet meinen Bruder Dilbert aufsuchen und ihm Bescheid sagen. Er ist bestimmt krank vor Sorge!", sourceObjective = "Sprecht mit Dilbert Tüftelzink im Zekkversteck.", completion = "Oh, dem Himmel sei Dank. Ich habe noch nicht einmal Waffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35725] = { id = 35725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Feenglanz" }
quests[35730] = { id = 35730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wunden kauterisieren", description = "Ihr habt meine geliebte Begleiterin, Nisha, gerettet. Ich stehe tief in Eurer Schuld.\n\nDie Eiserne Horde hat mich weggelockt, um uns zu trennen. Diesen Fehler werde ich nicht noch einmal begehen.\n\nSie haben sie schwer verletzt und ich befürchte, dass wir ihr weitere Schmerzen zufügen müssen, um die Heilung einzuleiten.\n\nKönntet Ihr einen brennenden Holzscheit aus dem Feuer in der Nähe holen und ihre Wunden ausbrennen?\n\nIch werde sie festhalten.", sourceObjective = "Besorgt ein brennendes Scheit und brennt damit Nishas Wunden aus.", progress = "Nisha muss das überstehen.", completion = "Danke. Ihre Wunden haben sich geschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35731] = { id = 35731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ba'ruun" }
quests[35732] = { id = 35732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shinri" }
quests[35733] = { id = 35733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Krallenpriester", description = "Dieser Hammer war einst als der Schnabelbrecher bekannt. In seinen letzten und finstersten Tagen benutzte Terokk ihn, um abstoßende, verdammenswerte Opferrituale durchzuführen.\n\nAm besten denkt man über diese Zeiten gar nicht erst nach.\n\nTerokk wurde tief in den Schatten weggesperrt, um sich zu erholen und vielleicht zu heilen.\n\nMit ihm in Verbindung zu treten, wird einen großen Aufwand erfordern. In der Zwischenzeit, erlaubt mir, Euch mehr von seinen glorreichen Heldentaten zu erzählen... aus Zeiten vor diesem schrecklichen Fluch.\n\nBitte legt den Hammer auf das Bildnis.", sourceObjective = "Legt Terokks Hammer auf das Bildnis von Terokk.", completion = "<Während Ihr den Hammer dem Bildnis zu Füßen legt, sieht Reshad Euch über die Schulter und spricht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35734] = { id = 35734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klauenkönig", description = "<Reshad beginnt mit einer Geschichte über die glorreichen Zeiten von Terokk, als Euer Blick auf die Zwillingsschwerter im Gürtel des Bildnisses fällt.\n\nIn Skettis schienen es noch normale Schwerter gewesen zu sein, aber jetzt vibrieren sie vor Energie, als ob sie auf die Worte des Schriftenbewahrers reagieren würden.>", sourceObjective = "Benutzt das Bildnis von Terokk, um Terokks Kampf gegen die Blutmähnen aufs Neue zu erleben. Tötet 30 Stumpfzähne der Blutmähnen, 20 ausgewachsene Blutmähnensaberon und Rudelführer Karash.", completion = "Das war nur eine von vielen derartigen Geschichten.\n\nKein einziger Arakkoa, ob tot oder lebendig, ist mit dem Klauenkönig vergleichbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[35735] = { id = 35735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss 021 – Berserkerschredder" }
quests[35736] = { id = 35736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schnee geschrieben", description = "Dies ist eine verblichene Seite aus dem Tagebuch von Schattenjägerin Bwu'ja. Es scheint sich um eine Skizze des Eingangs zur Sklavenbergwerk der Blutschläger zu handeln. Rokhan in Eurer Garnison dürfte daran sehr interessiert sein.", sourceObjective = "Bringt die zerfledderte Notiz zu Rokhan in Eurer Garnison.", completion = "Hervorragende Arbeit. Eure Dienste haben sich wie immer als wertvoll erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35737] = { id = 35737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schnee geschrieben", description = "Dies ist eine verblichene Seite aus Owynn Graddocks Tagebuch. Es scheint sich um eine Skizze des Eingangs zur Sklavenbergwerk der Blutschläger zu handeln. Bodrick Grau in Eurer Garnison dürfte daran sehr interessiert sein.", sourceObjective = "Bringt die zerfledderte Notiz zu Bodrick Grau in Eurer Garnison.", completion = "Hervorragende Arbeit. Eure Dienste haben sich wie immer als wertvoll erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35738] = { id = 35738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollständig Organisch", description = "Ihr habt also eine Schmugglerhöhle, hm?\n\nIch würde ja gern mit Euch handeln, Schätzchen, aber meine Laserkanone funktioniert momentan nicht einmal.\n\nAber passt auf. Seht Ihr die Urtume hier? Die Waffe der Arakkoa hat die ziemlich verbrutzelt. Die sind praktisch Holzkohle auf Beinen.\n\nBringt mir Holzkohle, um dieses Ding anzutreiben, dann habt Ihr Euren Handel.", sourceObjective = "Sammelt 30 frische Kohle von Urtumen.", progress = "Wenn Ihr das Zeug habt, können wir reden.", completion = "Das sollte reichen! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35739] = { id = 35739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollständig Organisch", description = "Oh, Ihr habt einen Handelsposten?\n\nFantastisch!\n\nMachen wir einen Handel. Ihr helft mir, meine Laserkanone aufzuladen, und Ihr bekommt etwas von diesem... Termo... Ultra... Obsidiglas für Eure Waffen.\n\nSeit die Urtume hier von der Arakkoawaffe getroffen wurden, bestehen sie praktisch aus Holzkohle. Besorgt mir etwas davon!", sourceObjective = "Sammelt 30 frische Kohle von Urtumen.", progress = "Diese verdammte, überholte Goblintechnik funktioniert nie richtig.", completion = "Das ist... ziemlich viel Holzkohle. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[35744] = { id = 35744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ende der Exekutionen", description = "Wir sind so schnell gekomm'n, wie wir konnten... aber es war zu spät. Die Eiserne Horde hat uns're Krieger gefangen genomm'n.\n\nEs besteht kein Zweifel, dass sie Informationen aus ihnen rausquetsch'n woll'n.\n\nIch fürchte, dass sie die Gefangenen hinricht'n werd'n, wenn sie mit ihrem Verhör fertig sind. Die Zeit wird knapp.", sourceObjective = "Tötet 3 Scharfrichterinnen des Eisernen Marsches.", completion = "Die Gefangenen sind zwar 'n bisschen mitgenomm'n, aber frei. Wir steh'n in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35745] = { id = 35745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Eisernen Horde", description = "Es wird berichtet, dass sich das Dunkle Portal kurz vor dem Angriff rot gefärbt hat. Sie nennen sich die Eiserne Horde.\n\nIhre Armee ist extrem gut ausgerüstet und es scheint unendlich viele von ihnen zu geben.\n\nSie haben bereits Burg Okril'lon und Burg Nethergarde eingenommen. Unsere Truppen an der Front könnten Eure Hilfe brauchen, {class}.", sourceObjective = "Tötet 8 Grunzer des Eisernen Marsches.", completion = "Aka'Magosh, Champion. Eure Anwesenheit auf dem Schlachtfeld hat die Truppen bestimmt motiviert.", sourceObjectiveStatus = "unverified-source-field" }
quests[35746] = { id = 35746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagert", description = "Unsere Truppen haben den Kanonen der Eisernen Horde nichts entgegenzusetzen. Ich weiß nicht, wie lange wir das noch durchhalten. Unsere Streitkräfte sind bereits zu stark dezimiert worden.\n\nWir müssen diese Kriegsmaschinen irgendwie aufhalten.", sourceObjective = "Sabotiert 3 Verwüster der Eisernen Horde.", completion = "Die Eiserne Horde wird eine Weile brauchen, um diese Verwüster zu reparieren. Throm-Ka, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35747] = { id = 35747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise zum Dach des Panzers", description = "Wir dürfen nicht riskieren, dass das Dunkle Portal reaktiviert wird. Es wird Zeit für den Todesstoß.\n\nThaelin dürfte mittlerweile wissen, wie der Panzer funktioniert. Nehmt ihn mit und setzt den Panzer direkt gegen das Dunkle Portal ein. Wir folgen Euch.", sourceObjective = "Sprecht mit Thaelin Schwarzamboss und begleitet ihn dann auf das Dach des Eisernen Weltenbrechers.", completion = "Damit... damit kann ich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[35748] = { id = 35748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subversive Späher", description = "Wir konnten einen Großteil unserer Schlachtpläne nicht umsetzen. Wir werden garantiert beobachtet.\n\nDie Eiserne Horde setzt wohl überall in den Verwüsteten Landen Späher ein. Der Sieg entgleitet uns.", sourceObjective = "Tötet 5 Späher der Eisernen Horde.", completion = "Ihr habt wie viele Späher getötet? Kein Wunder, dass wir unsere Pläne nicht umsetzen konnten...", sourceObjectiveStatus = "unverified-source-field" }
quests[35750] = { id = 35750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinnige Leutnants", description = "Wir sollten mehr über unseren neuen Feind in Erfahrung bringen.\n\nUnsere Späher haben einige Leutnants der Eisernen Horde identifiziert. Ihr Angriff ist so gut organisiert, dass er nicht nur auf Stammeswissen beruhen kann. Ihre Leutnants haben sicherlich Zugang zu geheimen Schlachtplänen.\n\nIhr seid <der einzige Soldat, dem/die einzige Soldatin> der; ich diese Mission anvertrauen kann, {name}.", sourceObjective = "Beschafft Schlachtpläne der Eisernen Horde.", progress = "Konntet Ihr Euch irgendwelche Schlachtpläne beschaffen?", completion = "Sehen wir uns diese Schlachtpläne mal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[35751] = { id = 35751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Nethergarde", description = "Die Eiserne Horde muss aus Narren bestehen, wenn sie glaubt, dass wir ihnen einen so strategisch wichtigen Ort wie Burg Nethergarde überlassen werden.\n\nUnsere Truppen lechzen danach, das Blut dieser Wilden zu vergießen, aber sie brauchen einen Champion wie Euch, der sie in die Schlacht führt.", sourceObjective = "Platziert die Flaggen der Horde in Burg Nethergarde.", completion = "Die Eiserne Horde wird uns bald fürchten, so wie sie sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[35759] = { id = 35759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 065 - Abandoned Cargo" }
quests[35760] = { id = 35760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahnbrecher der Vernichter", description = "Wenn die Schlachtpläne stimmen, die Ihr mitgebracht habt, dann tragen die Schreckensfelsoger ebenso große Schuld an dieser Verwüstung wie die Eiserne Horde. Es wird Zeit, dass wir diesen Ogern eine Lektion erteilen.\n\nDie Eiserne Horde stützt sich vor allem auf einen großen Oger in Schreckensfels, der sich Zahnbrecher nennt. Sein Tod wird ihre Schlachtpläne durchkreuzen.", sourceObjective = "Tötet Zahnbrecher den Vernichter.", completion = "Zahnbrecher ist tot? Gut. Die Horde wird eine Weile brauchen, um einen anderen Oger zu finden, der schlau genug ist, um ihnen nützlich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35761] = { id = 35761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergarde plündern", description = "Nachdem die Eiserne Horde Nethergarde erobert hatte, griffen wir an. Dort besiegten wir sie, doch brachten sie noch mehr Truppen durch das Portal und eroberten Burg Okril'lon. So vielen Seelen haben diese Wilden die Körper genommen.\n\nWir dürfen niemals jene vergessen, die ihr Leben bei der Schlacht um Nethergarde opferten. Wenn Ihr irgendwelche Andenken an die Gefallenen findet, dann bringt sie mir bitte.", sourceObjective = "Holt Meister Aitokks Axt, Nekas Giftfläschchen und den Schild von Aufseherin Struk.", progress = "Habt Ihr etwas gefunden?", completion = "Throm-Ka, {name}. Diese Andenken werden uns für immer an unsere Helden erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[35762] = { id = 35762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Schreckensfelsogern", description = "Die Dummheit der Schreckensfelsoger überrascht mich immer wieder. Die Eiserne Horde benutzt sie offensichtlich, um ihre eigenen finsteren Ziele voranzutreiben.\n\nTrotzdem müssen wir den Ogern zeigen, was passiert, wenn man sich der wahren Horde widersetzt. Es wird Zeit, diesen Schreckensfelsogern eine Lektion zu erteilen.", sourceObjective = "Tötet 8 Schreckensfelsoger.", completion = "Es ist wichtig, dass unsere Feinde erkennen, was geschieht, wenn man die wahre Horde angreift. Ich bin froh, dass es Euch gelungen ist, ihnen das zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35763] = { id = 35763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'mak Klingendreher", description = "Dank Eurer gesammelten Informationen wissen wir jetzt, dass der Angriff von Gar'mak Klingendreher, einem mächtigen Orc der Eisernen Horde angeführt wird. Er hat sich in Burg Okril'lon verschanzt.\n\nSein Tod wird den Krieg nicht beenden, aber die Kommunikation innerhalb der Eisernen Horde unterbrechen. Das wird uns wertvolle Zeit verschaffen, um weitere Streitkräfte zu sammeln und einen Schlachtplan für den Kampf gegen diese neue Bedrohung aufzustellen.", sourceObjective = "Tötet Gar'mak Klingendreher.", completion = "Es war mir eine Ehre, an Eurer Seite zu kämpfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35764] = { id = 35764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrillas Rache", description = "Die Schreckensfelsoger glauben, sie haben uns bezwungen? Sie alle sollen leiden. Hier, nehmt dieses Gift und träufelt etwas davon in ihren Ratteneintopf.\n\nDas Gift wird ihnen die Eingeweide zerfressen und zu einem langsamen und schmerzhaften Tod führen, so wie sie ihn verdienen.", sourceObjective = "Vergiftet die Nahrung der Schreckensfelsoger.", completion = "Ich wünschte, ich könnte ihre Gesichter sehen, wenn sie leiden. Ich hoffe, dass sie einen langsamen und schrecklichen Tod sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[35765] = { id = 35765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 049 - Bündel eines Abenteurers" }
quests[35766] = { id = 35766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe tote Arakkoa", description = "Ich habe ein sehr seltsames Problem und ich hoffe, dass Ihr mir helfen könnt. Ich weiß ehrlich gesagt nicht, an wen ich mich sonst wenden sollte.\n\nMeine Arbeiter behaupten, dass sie den Geist des Arakkoa sehen, der hier das Sagen hatte.\n\nIch weiß, wie verrückt das klingt, aber würdet Ihr mit meinem Geistifizierer 12000 zur Leiche gehen und das überprüfen?\n\nDamit kann man jeden Geist in der Nähe finden. Falls dort nämlich kein Geist ist, versuchen meine Leute einfach, sich vor der Arbeit zu drücken.", sourceObjective = "Benutzt den Geistifizierer 12000 und tötet den Geist von Krallenpriester Zekk.", completion = "Geister? Was Ihr nicht sagt. Wer hätte das gedacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[35778] = { id = 35778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand – Vignette Boss 020 – Uralter Klingenmeister – TSH" }
quests[35782] = { id = 35782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe tote Arakkoa", description = "Sagt, wo Ihr schon einmal hier seid, könnt Ihr mir da nicht bei einem größeren Problem helfen?\n\nMeine Arbeiter behaupten unablässig, dass sie den Geist der obersten Arakkoa sehen, die oft hier oben war.\n\nNatürlich glaube ich ihnen nicht, aber würdet Ihr mit dem Geistifizierer 12000 zu ihrer Leiche gehen und das überprüfen?\n\nWenn sie nicht verrückt sind, sollte das den Beweis liefern.", sourceObjective = "Benutzt den Geistifizierer 12000 und tötet den Geist von Krallenpriester Zekk.", completion = "Ihr macht Witze! Was für eine Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[35784] = { id = 35784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Boss" }
quests[35786] = { id = 35786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronzesieg" }
quests[35787] = { id = 35787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silbersieg" }
quests[35788] = { id = 35788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldsieg" }
quests[35797] = { id = 35797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Jäger", description = "Der Laser sollte einsatzbereit sein, sobald wir ihn hier eingerichtet haben. Aber da ist noch etwas, das ich brauche.\n\nEs gibt da einen Sporengänger, der im Delta gleich südöstlich hier auf Jagd geht. Auf seinem Gesicht trägt er einen Apparat, der einen starken Laser abfeuert – viel stärker als der, den wir hier haben.\n\nGenau den hätte ich gerne.\n\nWenn wir das kapitale Ding hier aufstellen, werden wir mehr abbauen als Ihr Euch je träumen lassen würdet!", sourceObjective = "Besorgt den organischen Laserapparat des schwarzen Jägers.", progress = "Vielleicht hätte ich erwähnen sollen, dass der Laser ziemlich... potent ist.", completion = "Perfekt. Machen wir ihn bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35798] = { id = 35798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Leuchtende Höhlenblüte" }
quests[35807] = { id = 35807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Erosian", description = "Der Sieg über Erosian hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Unglaublich! Zuerst seid Ihr dem Kochtopf und den Gronn entkommen, dann dem heißen Dampf und den brennenden Klauen. Erosians Tod wird unseren Spähern das Leben deutlich leichter machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35808] = { id = 35808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Erosian", description = "Der Sieg über Erosian hat Euch eine Trophäe eingebracht, die der Anerkennung würdig ist.\n\nBringt sie zu Maraad am Hochpass.", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Unglaublich! Zuerst seid Ihr dem Kochtopf und den Gronn entkommen, dann dem heißen Dampf und den brennenden Klauen. Erosians Tod wird unseren Spähern das Leben deutlich leichter machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35809] = { id = 35809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Dessicus", description = "Der Sieg über Dessicus hat Euch eine Trophäe eingebracht, die der Anerkennung würdig ist.\n\nBringt sie zu Maraad am Hochpass.", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt eine weitere tödliche Bestie in Gorgrond bezwungen.\n\nDessicus scherte sich nicht darum, wer seine Opfer waren. Sie alle fanden in seinen Salzteichen ihr Ende. Ihr habt viele Leben gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[35810] = { id = 35810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Dessicus", description = "Der Sieg über Dessicus hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt eine weitere tödliche Bestie in Gorgrond bezwungen.\n\nDessicus scherte sich nicht darum, wer seine Opfer waren. Sie alle fanden in seinen Salzteichen ihr Ende. Ihr habt viele Leben gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[35811] = { id = 35811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Kraterfürst Magmaro", description = "Der Sieg über den Kraterfürsten Magmaro hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ich merke schon, wie das Beben der Erde nachlässt. Sein Zorn richtete unermesslichen Schaden in dieser Welt an. Gut, dass er durch Eure Hand gefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[35812] = { id = 35812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Kraterfürst Magmaro", description = "Der Sieg über Kraterfürst Magmaro hat Euch eine Trophäe eingebracht, die der Anerkennung würdig ist.\n\nBringt sie zu Maraad am Hochpass.", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ich merke schon, wie das Beben der Erde nachlässt. Sein Zorn richtete unermesslichen Schaden in dieser Welt an. Gut, dass er durch Eure Hand gefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[35813] = { id = 35813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Fungusprätorianer", description = "Der Sieg über den Fungusprätorianer hat Euch eine Trophäe eingebracht, die der Anerkennung würdig ist.\n\nBringt sie zu Maraad am Hochpass.", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Die Rangari haben mir die Legenden vom Blutroten Sumpf erzählt – und dass noch niemand lebend von dort zurückgekehrt ist. Wenn dies der Grund dafür war, können wir jetzt beruhigt aufatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35814] = { id = 35814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Fungusprätorianer", description = "Der Sieg über den Fungusprätorianer hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Die Lachenden Schädel haben mir die Legenden vom Blutroten Sumpf erzählt – und dass noch niemand lebend von dort zurückgekehrt ist. Wenn dies ein Grund dafür war, können wir jetzt beruhigt aufatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35815] = { id = 35815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Charl Finsterschwinge", description = "Der Sieg über Charl hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Unser Vorhaben war bereits schwierig genug, ohne dass eine Riesenbestie wie Charl unseren Spähern das Leben zur Hölle macht und die Gronn provoziert.\n\nRuhm und Ehre, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[35816] = { id = 35816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Charl Finsterschwinge", description = "Der Sieg über Charl hat Euch eine Trophäe eingebracht, die der Anerkennung würdig ist.\n\nBringt sie zu Maraad am Hochpass.", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Unser Vorhaben war bereits schwierig genug, ohne dass eine Riesenbestie wie Charl unseren Spähern das Leben zur Hölle macht und die Gronn provoziert.\n\nIhr habt den Rangari mit diesem Sieg großes Leid erspart, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[35817] = { id = 35817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Roardan der Himmelsschrecken", description = "Der Sieg über Roardan hat Euch eine Trophäe eingebracht, die der Anerkennung würdig ist.\n\nBringt sie zu Maraad am Hochpass.", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Die Schreie dieses riesigen Rylaks ließen sich nicht ignorieren.\n\nNie konnte man sicher sein, ob sie aus der Ferne zu uns drangen oder ob plötzlich ein Schatten erscheinen würde, der uns den sicheren Tod bescheren würde. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35818] = { id = 35818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Roardan der Himmelsschrecken", description = "Der Sieg über Roardan hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Die Schreie dieses riesigen Rylaks ließen sich nicht ignorieren.\n\nNie konnte man sicher sein, ob sie aus der Ferne zu uns drangen oder ob plötzlich ein Schatten erscheinen würde, der uns den sicheren Tod bescheren würde. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35819] = { id = 35819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Khargax der Verschlinger", description = "Der Sieg über Khargax hat Euch eine Trophäe eingetragen, die der Anerkennung würdig ist.\n\nBringt dies zu Durotan in der Wildwacht.", sourceObjective = "Bringt die Trophäe zu Durotan in der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Die Lachenden Schädel haben sich von jeher von diesem Gebiet ferngehalten, weil Khargax trotz seiner Größe alles andere als behäbig ist. Sie werden erfreut sein, dass ihre ihm zum Opfer gefallenen Kameraden gerächt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[35820] = { id = 35820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmestrophäe: Khargax der Verschlinger", description = "Der Sieg über Khargax hat Euch eine Trophäe eingebracht, die es würdig ist, in Eurem Außenposten zur Schau gestellt zu werden. \n\nBringt sie zu Maraad, um Euren Ruhm zu mehren!", sourceObjective = "Bringt die Trophäe zu Maraad am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt uns allen einen großen Gefallen getan, {name}.\n\nTrotz all unserer Verluste in diesem Gebiet waren wir der Existenz dieser glitschigen Hydra kaum gewahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[35828] = { id = 35828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggrokultur vom Feinsten", sourceObjective = "Trefft Euch mit Thaelin Schwarzamboss am Wildwuchsbett.", completion = "Ah, perfekt. Die Karre läuft wieder, ehe Ihr Euch verseht.", sourceObjectiveStatus = "unverified-source-field" }
quests[35834] = { id = 35834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Genesaurier", description = "Erst walzt eine große Metallbestie in unser Lager, dann ein Genesaurier, der eine Welle aus reinem chaotischem Leben auf uns hetzt.\n\nWir müssen die Manifestationen beseitigen, die der Genesaurier hinterlassen hat, damit wir vor unserem Aufbruch möglichst viel bergen können.\n\nFalls Ihr uns helfen wollt, dann tötet bitte so viele der gewalttätigen Pflanzen, die uns angreifen, wie ihr nur könnt.", sourceObjective = "Vernichtet 9 wilde Überwucherungen.", completion = "Ein guter Anfang. Die Gewächse des Genesauriers sind das reinste Chaos und müssen konsequent gejätet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35835] = { id = 35835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Jäger", description = "Wir sind bereit, den Laser aufzustellen, aber um durch dieses Zeug zu kommen, werden wir mehr Feuerkraft brauchen.\n\nDer schwarze Jäger geht im Delta direkt südöstlich von hier auf die Pirsch. Auf dem Gesicht trägt er einen Apparat, der einen Laser abfeuert, der weitaus stärker ist als der, den wir hier haben.\n\nGenau den brauchen wir.\n\nBesorgt ihn, während wir den Laser einrichten.", sourceObjective = "Besorgt den organischen Laserapparat des schwarzen Jägers.", progress = "Übrigens, dieser Laser ist äußerst gefährlich. Seid bloß vorsichtig!", completion = "Na dann los, werfen wir das Ding an!", sourceObjectiveStatus = "unverified-source-field" }
quests[35836] = { id = 35836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 008 - Der Lunker" }
quests[35837] = { id = 35837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Verdeckte Recherchen", description = "Eine meiner besten Feldagentinnen, Jeanine Amrell, ist tief im feindlichen Gebiet im nördlichen Nagrand stationiert.\n\nSie brachte in Erfahrung, dass die Kriegsfürsten der orcischen Klans ein geheimes Treffen am Wachposten von Mok'gol planen.\n\nDies könnte die entscheidende Gelegenheit für uns sein, uns einen besseren Einblick in ihre Pläne für die Zukunft zu verschaffen.\n\nIhr müsst Euch sofort mit Agentin Amrell treffen. Vielleicht ist dies unsere Chance, {name}!", sourceObjective = "Sucht nach Jeanine Amrell beim Versteckten Lager in Nagrand.", completion = "<Nach den Verletzungen an ihrem Körper zu urteilen, hat die Agentin heftigen Widerstand geleistet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35838] = { id = 35838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat der Kriegsherren", description = "Als Ihr sie näher untersucht, bemerkt Ihr um ihren Hals gebunden ein Stück Lederpergament.\n\nFolgende Worte scheinen in großem Zorn hinein geritzt worden zu sein:\n\n\"WERDET ZEUGEN DES SCHICKSALS, DAS JENE EREILT, DIE SICH DER EISERNEN HORDE WIDERSETZEN!\"", sourceObjective = "Findet heraus, wer der Urheber dieser Nachricht ist.", completion = "Ich bin froh, dass ich Euch gefunden habe, {name}. Ich bin untergetaucht, als die Orcs des Kriegshymnenklans unseren Schlupfwinkel beim Versteckten Lager angegriffen haben.\n\nIhr hättet sehen sollen, wie tapfer Jeanine Widerstand geleistet hat. Selbst als sie begannen, sie zu foltern, gab sie nicht preis, dass wir zu zweit waren.\n\nSie hatte einen eisernen Willen, die Gute.", sourceObjectiveStatus = "unverified-source-field" }
quests[35839] = { id = 35839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegspläne", description = "Ich habe Jeanines Notizbuch sichern können. Sie hat mehrere Schlüsselgegenstände in den Gebäuden in der Nähe identifiziert, die sie näher untersuchen wollte. Aber dazu ist sie vor ihrem Tod nicht mehr gekommen.\n\nDas Einzige, was wir noch für sie tun können, ist, ihre Arbeit fortzuführen.\n\nUntersucht das Lager auf geheime Informationen. Ich werde derweil die Orcs ablenken.", sourceObjective = "Findet das maßstabsgetreue Modell von Gorgorek, die Miniaturkriegsmaschine und die Karte des Tanaandschungels.", completion = "Wirklich erstaunlich, {name}. Jetzt haben wir den entscheidenden Beweis für Grommashs Absichten.\n\nVielleicht verschafft uns dies den entscheidenden Vorsprung vor der Eisernen Horde. Großartige Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35840] = { id = 35840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehle abfangen", description = "Einfach alles dreht sich um Informationen, <mein Freund/meine Liebe>. Je mehr wir über Höllschreis Pläne wissen, umso leichter können wir sie auch vereiteln.\n\nDie Orcs von Mok'gol dienen Höllschrei oft als Kuriere, die seine Missionsbefehle von hier zu seinen Außenposten auf ganz Draenor tragen.\n\nTötet diese Reiter und bergt alle Befehle, die Ihr findet.", sourceObjective = "Sammelt Missionsbefehle vom Frostfeuergrat, aus dem Schattenmondtal und von den Spitzen von Arak.", progress = "Habt Ihr etwas für mich?", completion = "Hervorragende Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35841] = { id = 35841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Rudelführer", description = "Die Verantwortung für die Einsätze am Wachposten von Mok'gol trägt ein mächtiger Krieger namens Rudelführer Vor'gash.\n\nWenn wir diesen grausamen Rädelsführer unschädlich machen, können wir ihre Kommunikation für einige Zeit lahmlegen.\n\nIhr findet Vor'gash auf Patrouille im Nordosten des Geländes.\n\nTötet ihn.", sourceObjective = "Tötet Rudelführer Vor'gash.", completion = "Mir ist schon so Manches über Vor'gash zu Ohren gekommen. Ich bin erleichtert, dass er uns keinen Ärger mehr machen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[35842] = { id = 35842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Rudelführer", description = "Der Drahtzieher am Wachposten von Mok'gol is' Rudelführer Vor'gash.\n\nWir erledig'n ihn, un' sie sind lahmgelegt.\n\nIhr findet ihn auf seiner Patrouille des Geländes im Nordosten.\n\nTötet ihn.", sourceObjective = "Tötet Rudelführer Vor'gash.", completion = "Ich kenn diesen Vor'gash. Nur gut, dass er uns keinen Ärger mehr mach'n wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[35843] = { id = 35843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Verdeckte Recherchen", description = "Grade zur recht'n Zeit, Kommandant.\n\nVor einiger Zeit hab' ich einen meiner besten Schattenjäger tief ins Feindesland rausgeschickt.\n\nEr sagt, dass die Kriegsfürsten so'n geheimes Treffen am Wachtposten von Mok'gol abhalt'n woll'n.\n\nWenn das mal nicht DIE Chance ist, rauszufind'n, was Höllschrei gerade ausbaldowert.\n\nGeht jetzt un' trefft Euch mit Zasta. Er wird Euch sagen, was als Nächstes zu tun ist.", sourceObjective = "Findet Schattenjäger Zasta beim Versteckten Lager in Nagrand.", completion = "<Nach den Verletzungen an seinem Körper zu urteilen, hat der Schattenjäger heftigen Widerstand geleistet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35844] = { id = 35844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat der Kriegsherren", description = "Als Ihr ihn näher untersucht, bemerkt Ihr um seinen Hals gebunden ein Stück Lederpergament.\n\nFolgende Worte scheinen in großem Zorn hinein geritzt worden zu sein:\n\n\"WERDET ZEUGEN DES SCHICKSALS, DAS JENE EREILT, DIE SICH DER EISERNEN HORDE WIDERSETZEN!\"", sourceObjective = "Findet heraus, wer der Urheber dieser Nachricht ist.", completion = "Ich such schon ewig nach Euch, Kommandant. Ich wusste genau, dass Ihr kommt, aber diese fiese Orcfrau hat Euch erwischt, bevor ich Euch warn'n konnte.\n\nWenigstens konnte ich Euch noch retten. Armer Zasta. Er konnte so was nich' kommen seh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[35845] = { id = 35845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegspläne", description = "Ich hab' Zastas Notizen sichern könn'. Er hat geseh'n, dass die Anführer des Kriegshymnenklans sich oft in den Gebäud'n in der Nähe treffen.\n\nDas Einzige, was wir noch für ihn tun könn', is', seinen Spuren nachzugeh'n.\n\nUntersucht das Lager auf geheime Informationen. Ich werd' die Orcs ablenken.", sourceObjective = "Findet das maßstabsgetreue Modell von Gorgorek, die Miniaturkriegsmaschine und die Karte des Tanaandschungels.", completion = "Jetzt hab'n wir Beweise für Höllschreis Absichten.\n\nVielleicht verschafft uns das 'nen Vorsprung vor der Eisernen Horde. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35846] = { id = 35846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehle abfangen", description = "Es dreht sich alles immer um Informationen, Kommandant. Je mehr wir über Höllschreis Pläne wissen, umso leichter könn'n wir sie auch vereiteln.\n\nDie Orcs von Mok'gol mach'n öfter mal den Kurier für Höllschrei und überbring'n seine Missionsbefehle von hier aus zu den Außenposten auf ganz Draenor.\n\nTötet diese Reiter un' bergt alle Befehle, die Ihr in die Finger kriegt.", sourceObjective = "Sammelt Missionsbefehle vom Frostfeuergrat, aus dem Schattenmondtal und von den Spitzen von Arak.", progress = "Habt Ihr was für mich?", completion = "Das is' gut, {name}. Das is' echt gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[35847] = { id = 35847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Leerenseher Kalurg" }
quests[35861] = { id = 35861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Nachtflutnest", description = "Wir haben Berichte erhalten, dass Kriegsschiffe der Eisernen Horde bei einer kleinen Insel direkt südlich des Schattenmondtals vor Anker gegangen sind.\n\nWir haben ein paar Späher entsandt, aber noch nichts von ihnen gehört. Wir sollten der Sache nachgehen.\n\nDungar Trinkfest hält einen Greifen für Euch bereit, bis Ihr ausrücken könnt, Kommandant.", sourceObjective = "Begebt Euch zum Nachtflutnest.", completion = "Diese Wilden haben keine Ehre im Leib! Höchste Zeit, dass wir uns die Präsenz der Eisernen Horde auf dieser Insel vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35865] = { id = 35865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 018 - Leerenschleim" }
quests[35866] = { id = 35866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente" }
quests[35867] = { id = 35867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Jedes bisschen hilft." }
quests[35868] = { id = 35868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Artefaktfragmente", progress = "Je mehr, desto besser.", completion = "Es muss Euch große Mühe bereitet haben, uns das zu bringen. Ihr habt Euch diese Belohnung verdient." }
quests[35869] = { id = 35869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede MENGE Artefaktfragmente" }
quests[35870] = { id = 35870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basiliskenschlächter", description = "Basilisk ist eine von Nishas Lieblingsspeisen. Dies hier sind ihre Jagdgründe, was wahrscheinlich der Grund war, warum diese Bastarde der Eisernen Horde sie gefangen nehmen konnten.\n\nWarum nur haben sie sich die Mühe gemacht, sie auf diese Weise zu überwältigen? Vielleicht können wir zusammen die Antwort auf diese Frage finden, wenn wir sie für ihre Vergehen bestrafen.\n\nJetzt benötigt Nisha zunächst einmal Nahrung. Würdet Ihr für sie auf die Jagd gehen, während ich mich um sie kümmere?", sourceObjective = "Besorgt 9 Stücke Basiliskenfleisch von Steinschlurferbasilisken oder verwesenden Basilisken.", progress = "<Nisha schnieft heftig.>", completion = "<Nisha schluckt das Fleisch in einem Bissen herunter.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35871] = { id = 35871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Jedes bisschen hilft." }
quests[35872] = { id = 35872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Artefaktfragmente", progress = "Je mehr, desto besser.", completion = "Es muss Euch große Mühe bereitet haben, uns das zu bringen. Ihr habt Euch diese Belohnung verdient." }
