quests[35875] = { id = 35875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 024 - Ophiis" }
quests[35876] = { id = 35876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Nachtflutnest", description = "Wir krieg'n Berichte, dass Kriegsschiffe der Eisernen Horde auf einer kleinen Insel direkt südlich des Schattenmondtals vor Anker gegangen sind.\n\nWir haben 'n paar Späher hingeschickt, aber seitdem nix mehr von ihnen gehört. Wir sollten der Sache nachgeh'n.\n\nBron Himmelshorn hält einen Ryklak für Euch bereit, bis Ihr ausrücken könnt, Kommandant.", sourceObjective = "Begebt Euch zum Nachtflutnest.", completion = "Diese Wilden haben keine Ehre im Leib! Höchste Zeit, dass wir uns die Präsenz der Eisernen Horde auf dieser Insel vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35877] = { id = 35877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 005 - Windrufer Korast" }
quests[35878] = { id = 35878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheitsmaßnahmen", description = "Wie sich herausstellt, hat die Resonanzfrequenz der Batterien die Wildtiere in der Gegend in Aufruhr versetzt. Ich... Ich glaube, erst gerade hat mich eins dieser Wildschweine angeschaut und sich dabei die Lippen geleckt.\n\nIch werde mich erkenntlich zeigen, wenn Ihr nur... alles, was Euch dort unten den Weg kreuzt, unschädlich macht. Was auch immer es sein mag, tötet es, ja?", sourceObjective = "Tötet 15 Sumpfbewohner.", completion = "Fantastisch! So was nennt man Abenteuer der alten Schule.", sourceObjectiveStatus = "unverified-source-field" }
quests[35879] = { id = 35879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheitsmaßnahmen", description = "Die Batterien, die ich im Sumpf verloren habe, scheinen die Wildtiere in helle Aufruhr versetzt zu haben. Ohne einen Kampf werden sie sich nicht bergen lassen, doch gegen wen?\n\nWenn Ihr könnt, schaltet alle Kreaturen aus, die dort Euren Weg kreuzen. Ich möchte tunlichst vermeiden, dass mich eine dieser Riesenbestien bis zurück zum Ausgrabungsort verfolgt.\n\nIch werde Euch für Eure Mühen belohnen.", sourceObjective = "Tötet 15 Sumpfbewohner.", completion = "Genau so habe ich mir das vorgestellt. Ihr seid zäh wie Leder.", sourceObjectiveStatus = "unverified-source-field" }
quests[35880] = { id = 35880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn und Weisheit", description = "Die Bestien der westlichen Schlucht liefern sich einen nicht enden wollenden Krieg mit den Kreaturen der östlichen Wildnis.\n\nWenn eine Seite die Oberhand über die andere gewänne, würde der Sieger das Schicksal von ganz Draenor besiegeln.\n\nDer Lachende Schädel möchte sein zerstörtes Dorf rächen. Ich habe sie angewiesen, ihre Gefühle an den Kreaturen in der Nähe auszulassen, sodass unser Außenposten hier keinen Schaden davonträgt.\n\nSeid so gut und überwacht ihr Handeln, Kommandant. Noch traue ich dem Lachenden Schädel nicht.", sourceObjective = "Sprecht mit dem Knochigen Xais am Leidensgrat.", completion = "Ich kann die Zukunft meiner Feinde aus den Knochen lesen. Sie sind dem Tod geweiht!", sourceObjectiveStatus = "unverified-source-field" }
quests[35881] = { id = 35881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinen der Ersten Bastion" }
quests[35882] = { id = 35882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutos Absicht", description = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "Genau SO entflieht man einer Gladiatorgrube!\n\nIhr lasst es fast wie Spaß aussehen. Eure Waffen ziert ein wahrer Regenbogen verschiedenster Blutgruppen.\n\nEuch werde ich von nun an folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35883] = { id = 35883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaandaams Fäuste", description = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", completion = "Jahrelang haben die Oger mich gezwungen, zu kämpfen, zu töten und zu salutieren. Jedes Mal ließ es meine Seele bluten.\n\nDoch dank Euch werde ich nun nie wieder einem Oger salutieren müssen.\n\nIhr habt mir zu meiner Freiheit verholfen, und ich habe beschlossen, diese Freiheit in den Dienst Eures Banners zu stellen.\n\nVon nun an werde ich Euch salutieren, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[35884] = { id = 35884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zielgerade", description = "Wenn sie bisher nicht wütend waren, sind sie es jetzt auf jeden Fall. Wir werden hier oben auf dem Panzer keine Minute überleben!\n\nSchließen wir uns den anderen an und machen, dass wir hier rauskommen!!", sourceObjective = "Flieht zu den Docks.", completion = "Kaum einer hätte es geglaubt, aber hier stehen wir. Immer noch am Leben, mit einer ganzen Streitmacht auf unseren Fersen.\n\nUnser Schiff wartet auf uns. Sollen wir in See stechen?", sourceObjectiveStatus = "unverified-source-field" }
quests[35885] = { id = 35885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maraudon (Tückische Höhle) - Belohnungsquest" }
