quests[35894] = { id = 35894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbruch (Bonus) - Belohnungsquest" }
quests[35895] = { id = 35895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Fall", description = "<Erneut umgibt Euch Reshads Stimme.>\n\nTerokk war ein mächtiger und respektierter König, der von seinem Volk geliebt wurde.\n\nSeine Weisen waren ihm allerdings nicht so ergeben. In ihrer Gier, Himmelsnadel zu kontrollieren, verschworen sie sich gegen ihn.", sourceObjective = "Benutzt das Bildnis von Terokk, um Terokks Ende nachzuerleben. Sucht nach Lithic, versammelt 5 ausgestoßene Klauenwachen, tötet 20 wahnsinnige Ausgestoßene und benutzt das Auge von Anzu.", completion = "Seit dem Tag haben die Weisen das Sagen in Himmelsnadel, nennen sich jetzt die Jünger von Rukhmar und behaupten, die Verkünder ihres Willens zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35896] = { id = 35896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Avatar Terokks", description = "Mein langer Schlaf wurde von Träumen über die Vergangenheit unterbrochen. Ich habe wieder meine alten Feinde niedergestreckt. Erneut sah ich, wie meine Tochter starb.\n\nIhr wart auch dort. Ich spürte Eure Anwesenheit in meinen Träumen. Und auch Eure Vergangenheit wurde mir offenbart.\n\nJemand hat unsere Schicksale miteinander verwoben. Es ist Eure Aufgabe, mein Volk zu beschützen, und die meine, Eure Feinde zu vernichten.\n\nDie Zerschmetterte Hand sammelt sich in der Messerfaustfestung. Wenn es nach ihr ginge, würde sie dieses Land für die Eiserne Horde einnehmen.\n\nNehmt meine Macht und zusammen werden wir sie zerschlagen.", sourceObjective = "Sprecht mit Terokks Geist, um seine Kraft zu empfangen. Tötet 25 Kämpfer der Zerschmetterten Hand, 4 Grubenmeister der Zerschmetterten Hand und stellt Kargath Messerfaust.", completion = "Die Zerschmetterte Hand ist nur noch ein Scherbenhaufen, und der Avatar Terokks wandelt nun unter uns.\n\nAls ich Euch in Skettis Macht versprochen habe, dachtet Ihr da wirklich, ich würde keine weiteren Bedingungen stellen? Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[35897] = { id = 35897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das fehlende Stück", description = "Terokks Tochter Lithic war eine erfahrene Jägerin, fand aber ihre wahre Berufung als Goldschmiedin.\n\nSie stellte diesen Armreif als Geschenk für ihren Vater her, der ihn viele Jahre lang trug. Erst nach dem Tod von Lithic zog er den Armreif ab, da die Erinnerung an sie für den alten König unerträglich war.\n\nLegt den Armreif auf das Bildnis und ich erzähle Euch von Terokks Untergang.", sourceObjective = "Platziert Lithics Geschenk auf dem Bildnis von Terokk.", completion = "<Ihr streift den Armreif vorsichtig über den Arm des Bildnisses.>", sourceObjectiveStatus = "unverified-source-field" }
quests[35898] = { id = 35898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 005 - Metzelblüte" }
