quests[35904] = { id = 35904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelstiefen (Alles) - Belohnungsquest" }
quests[35905] = { id = 35905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgungsabwurf", description = "Eure Arbeiter dort unten haben ihre Ernte eingeholt und sind bereit, Vorräte an Eure Garnison zu liefern. Dieses Mal müsst Ihr Euch keine Sorgen um die Sicherheit Eurer Karawane machen. Ich werde eine Rangarieskorte entsenden, um sie aus den Wäldern zu geleiten und sie zu schützen.\n\nDie Exarchen werden Euch stets im Auge behalten.\n\nEure Vorräte sollten bereits auf Euch warten, wenn Ihr wieder in Eurer Garnison eintrefft. Viel Glück mit Eurem Feldzug, {name}!", sourceObjective = "Sprecht mit Baros Alexston in Eurer Garnison im Schattenmondtal.", completion = "Kommandant! Surrzisch ist soeben mit Euren Arbeitern im Schlepptau hier eingetroffen. Wir haben jetzt einen riesigen Überschuss an Nahrung und Versprechen, dass noch mehr kommen wird.\n\nScheinbar haben die Draenei sogar noch ein paar andere Ressourcen beigesteuert. Wirklich gute Arbeit! Was sollen wir als Nächstes bauen?", sourceObjectiveStatus = "unverified-source-field" }
quests[35906] = { id = 35906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Wahnsinniger \"König\" Sporeon" }
quests[35907] = { id = 35907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versuchter Mord", description = "Eure Schankwirtin Lunzul liegt im Sterben, Kommandant. Sie wurde vergiftet und braucht sofort ein Gegengift.\n\nEiner Euer Späher hat berichtet, dass er vor Kurzem einen Orc der Zerschmetterten Hand in der Nähe gesehen hat. Das ist unsere beste Chance.\n\nIm Osten gibt es ein kleines Lager der Arakkoa, das sich in der Nähe einer bekannten Siedlung der Zerschmetterten Hand befindet. Ich schlage vor, wir beginnen mit unserer Suche dort.\n\nIch habe bereits mit Eurem Flugmeister gesprochen, damit er uns einen Flug dorthin reserviert. Jede Sekunde zählt.", sourceObjective = "Sprecht mit Hutou Federwind, um Euren Flug zur Schattenwacht anzutreten.", completion = "Diese Leichen sind ganz frisch. Die Mörder müssen noch in der Nähe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35908] = { id = 35908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Steinsplitter-Brutmutter" }
