quests[35913] = { id = 35913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinerner Kern (Heroisch) - Belohnungsquest" }
quests[35914] = { id = 35914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Internal: Default Invasion Reward", description = "Seit einer Stunde erschüttern Erdbeben die Garnison, und einige der Späher haben sich noch nicht zurückgemeldet.", sourceObjective = "Schlagt die Invasion Eurer Garnison durch die Brecher zurück.\n\n(Sprecht erneut mit Unteroffizier Grimmkiefer, um zu beginnen.)", sourceObjectiveStatus = "unverified-source-field" }
quests[35915] = { id = 35915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versuchter Mord", description = "Kolrigg liegt im Sterben, Kommandant. Er wurde vergiftet und braucht 'n Gegengift, bevor's zu spät ist.\n\nEiner Euer Späher hat berichtet, dass er vor Kurzem 'nen Orc der Zerschmetterten Hand in der Nähe gesehen hat. Ich behaupte mal, das ist unsre beste Chance.\n\nIm Osten liegt 'n kleines Lager der Arakkoa, das sich in der Nähe von'ner bekannten Siedlung der Zerschmetterten Hand befindet. Wir sollt'n unsre Suche dort beginnen.\n\nIch hab' bereits mit Eurem Flugmeister gesprochen, damit er uns 'nen Flug nach dorthin reserviert. Jede Sekunde zählt.", sourceObjective = "Sprecht mit Firn Windflitzer, um Euren Flug zur Schattenwacht anzutreten.", completion = "Jawoll, diese Leichen sind ganz sicher noch frisch. Sie können nicht weit gekommen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[35919] = { id = 35919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Opfer" }
quests[35920] = { id = 35920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 019 - Tura'aka" }
quests[35921] = { id = 35921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brot und Spiele", description = "He, <gnä' Herr/gnä' Frau>, dieser Taugenichts will mich nicht einlassen. Würdet Ihr Euch gerne etwas Bares verdienen?\n\nMein Boss veranstaltet Kämpfe im Ring der Prüfung. Ihr seht aus, als hättet Ihr das Zeug zu so was.\n\nIhr solltet einen Kampf wagen.", sourceObjective = "Sprecht mit Dexyl Todesklinge im Ring der Prüfung.", completion = "He da, Alter. hat Lucy Euch geschickt? Gutes Mädchen.\n\nJa... Ihr solltet Euch hier gut machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35922] = { id = 35922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brot und Spiele", description = "He, <gnä' Herr/gnä' Frau>, dieser Taugenichts will mich nicht einlassen. Würdet Ihr Euch gerne etwas Bares verdienen?\n\nMein Boss veranstaltet Kämpfe im Ring der Prüfung. Ihr seht aus, als hättet Ihr das Zeug zu so was.\n\nIhr solltet einen Kampf wagen.", sourceObjective = "Sprecht mit Dexyl Todesklinge im Ring der Prüfung.", completion = "He da, Alter. hat Lucy Euch geschickt? Gutes Mädchen.\n\nJa... Ihr solltet Euch hier gut machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35923] = { id = 35923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 006 - Jäger Schwarzzahn" }
quests[35924] = { id = 35924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Assassinen", description = "Ihr Gift ist wirkungsvoller, als ich gedacht hatte. Wir müssen den Orc finden, der es hergestellt hat.\n\nMeisterassassinen hinterlassen immer ein Zeichen auf ihren Opfern. Es ist wie eine Visitenkarte, mit der sie den Ruhm der Tat in ihren Kreisen für sich beanspruchen.\n\nUnd wir haben es hier ganz sicher mit einem solchen Meisterassassinen zu tun.\n\nWir sollten uns aufteilen und bei den Leichen nach einem solchen Zeichen suchen. Das könnte uns zu dem Schöpfer des Gifts führen. Wir treffen uns dann unten am Hügel, Kommandant.", sourceObjective = "Untersucht die Leichen der wachsamen Ausgestoßenen nach einem Zeichen des Meisters.", progress = "Hattet Ihr Glück? Ich konnte nichts finden.", completion = "Was habt Ihr gefunden? Zeigt her.", sourceObjectiveStatus = "unverified-source-field" }
quests[35925] = { id = 35925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gronnstrategie", description = "Raz,\n\nEure Befehle lauten, vier weitere Gronn gefangen zu nehmen, um sie in Waffen zu verwandeln.\n\nVon Eurer ersten Gruppe hat nur einer den Prozess überlebt.\n\nEiner hat gnadenlos unsere Soldaten angegriffen und musste eingeschläfert werden. Ein weiterer fiel einer Fehlzündung zum Opfer, als er ausgerüstet wurde. Und wieder ein anderer ist im Schlaf auf seine Kanonen gerollt. Die Sauerei haben wir immer noch nicht ganz beseitigt.\n\nVerlasst Euch darauf, Eure Bemühungen sind nicht umsonst.\n\n- Hauptmann Brak", sourceObjective = "Bringt die Gronnkontrollbefehle zu Rexxar auf der Brecherkuppe.", progress = "Gronn als Waffen einsetzen? Falls sie Erfolg haben...", completion = "Das sind schlimme Neuigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[35926] = { id = 35926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Assassinen", description = "Wir müss'n den Orc find'n, der das Gift gemischt hat, wenn wir ein Gegenmittel herstellen woll'n.\n\nMeisterassassinen lass'n immer ein Zeichen auf ihren Opfern zurück. Damit beanspruchen Sie den Ruhm der Tat für sich. Und glaubt mir, wir hab'n es hier ganz sicher mit 'nem Meister zu tun.\n\nLos, wir teilen uns auf und suchen bei den Leichen nach seinem Zeichen. Das führt uns zum Mörder. Wir treff'n uns dann unten am Hügel, Kommandant.", sourceObjective = "Untersucht die Leichen der wachsamen Ausgestoßenen nach einem Zeichen des Meisters.", progress = "Habt Ihr etwas gefunden?", completion = "Was ist das? Zeigt her!", sourceObjectiveStatus = "unverified-source-field" }
quests[35927] = { id = 35927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassenengehirn", progress = "Ein Gehirn ist ein lebenswichtiges Organ. Aber für diese Untoten? Fragwürdig.", completion = "Gut gemacht, {name}. Ein Gehirn zu transportieren ist nicht einfach. Ich meine, die sind so verflucht glitschig." }
quests[35928] = { id = 35928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischschlitzer braucht Knochen", progress = "Ich habe jede Menge Fleisch. Kauft doch welches!\n\nWas ich wirklich brauche sind Knochen. Nagrands Vieh ist das herzhafteste in ganz Draenor. Seine Knochen sind von hervorragender Qualität.\n\nIch koche das leckerste Süppchen, das Ihr je gekostet habt. Ich werde diesem Groggelfitz schon zeigen, wer hier der beste Koch ist.", completion = "Wenn das kein guter Anfang ist. Ich werfe diese gleich in die Brühe.\n\nBringt mir mehr davon." }
quests[35929] = { id = 35929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefschwarze Grotte - Belohnungsquest" }
quests[35930] = { id = 35930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefschwarze Grotte (Bonus) - Belohnungsquest" }
quests[35931] = { id = 35931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 016 - Späher des Kriegshymnenklans" }
quests[35932] = { id = 35932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 026 - Taktiker des Kriegshymnenklans" }
quests[35933] = { id = 35933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroths letztes Gefecht", description = "Unzählige Male schon habt Ihr Euch aussichtslosen Kämpfen und unaussprechlichen Übeln gestellt – und seid als <Sieger/Siegerin> hervorgegangen. Und nun seid Ihr ein weiteres Mal dem Ruf gefolgt, bereit, Euer Leben für diese Welt zu riskieren, die Ihr liebt – unsere Welt.\n\nIhr seid Azeroths letzte Hoffnung, {name}.\n\nDie vor uns liegenden Herausforderungen mögen bedrohlich sein, doch würde ich mit der Durchführung dieser Mission niemand anderen betrauen wollen.\n\nDie Feinde an der Front könnten über die Informationen verfügen, die wir benötigen, um diesen Krieg zu gewinnen. Findet und vernichtet sie!\n\nGeht jetzt, {name}! Für Azeroth!", sourceObjective = "Beschafft Euch das Schreiben der Eisernen Horde von einem Mitglied der Eisernen Horde am Fuße des Dunklen Portals.", sourceObjectiveStatus = "unverified-source-field" }
quests[35934] = { id = 35934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nishas Rache", description = "Seit ich zu meiner letzten Jagd aufgebrochen bin, ist die Eiserne Horde immer näher gekommen und hat ihre Positionen verstärkt.\n\n<Ein Grinsen breitet sich auf Rexxars Lippen aus.>\n\nSie haben eine zielreiche Umgebung geschaffen.\n\nIch muss Nisha weiterhin gesundpflegen. Geht Ihr an meiner Stelle. Erfüllt sie mit der Angst und dem Schmerz, die sie ihr zugefügt haben.\n\nMögen ihre Schreie die Schlucht erfüllen!", sourceObjective = "Tötet 10 Grunzer der Grom'kar.", completion = "Danke, {name}. Nisha ist fast wieder gesund.", sourceObjectiveStatus = "unverified-source-field" }
quests[35935] = { id = 35935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Eisernen Horde!", description = "Rauch steigt auf am Horizont... Die Eiserne Horde ist im Anmarsch.", sourceObjective = "Schlagt die anrückende Eiserne Horde zurück.", completion = "Die Eiserne Horde ist eine Bedrohung. Lasst sie uns bis auf den letzten Mann vernichten. Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[35937] = { id = 35937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelfenohr", progress = "Bringt mir eins, wo noch schicker Schmuck dran hängt, dann bekommt Ihr einen Bonus.", completion = "Pah, keine Ohrringe oder so. Viel Glück beim nächsten Mal, {class}." }
quests[35938] = { id = 35938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinzinken", progress = "Wusstet ihr, dass selbst Fisch besser riechen kann als wir?", completion = "Ha, ja, ein bisschen unnützes Wissen für Euch: Diese spitze Trophäe ist ein Beweis dafür, dass Ihr da draußen einen Goblin getötet habt. Gut gemacht! Hier ist eine kleine Extrabelohnung für Euren harten Einsatz." }
quests[35939] = { id = 35939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taurenhuf", progress = "Seid Ihr schon einmal einem Taurenschurken begegnet, {name}?", completion = "Natürlich nicht! Ich meine, seht Euch nur diese Dinger an... Die machen so viel Krach, dass man damit nicht einfach so herumschleicht." }
quests[35940] = { id = 35940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orczahn", progress = "Es ist egal, welcher Zahn. Ein Schneidezahn... Eckzahn, vorderer Backenzahn, egal. Einen Orczahn erkenne ich, wenn ich ihn sehe.", completion = "Meine Güte... da hat wohl jemand seine Zähne nicht geputzt, was? Hah, nehmt dies als Belohnung, {name}." }
quests[35941] = { id = 35941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollfüße", progress = "Glaubt mir, ich würde Euch nicht um ihre Füße bitten, wenn ich nicht müsste.", completion = "Oh Mann <hustet>... seht zu, dass das Ding schnell in meinen Eimer kommt." }
quests[35942] = { id = 35942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandarenfell", progress = "Moment mal... woher weiß ich, dass Ihr das einem von der Horde abgezogen habt und nicht einem Eurer Freunde?", completion = "Das war ein Witz! Ein Witz! Wir wissen doch alle, dass Ihr eine Musterjägerin des Sturmschilds seid, {name}. Hier, nehmt das als Lohn." }
quests[35943] = { id = 35943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 026 - Duretha" }
quests[35944] = { id = 35944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Gorenzahn", description = "Dieser Zahn ist ein Beweis für Eure Stärke im Töten von Goren, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Zahn zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Wir sind beeindruckt von Eurer Fähigkeit, die Goren zu töten. Sie sind unerbittlich und unersättlich und können die Unvorbereiteten überwältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35945] = { id = 35945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greblin Flinkzünd", description = "Ich hänge hier schon ewig rum!\n\nIch bin hier rumgeflogen, hab das Gebiet für Nixxie vermessen und dann... BÄMM! Einer dieser blöden Oger hat einen Stein nach mir geworfen. Hat mich direkt getroffen!\n\nMein Gleiter ist abgestürzt und ich sitz hier fest... und, Mann, ist das unbequem.\n\nHelft mir bitte runter, ja? Ich sorge auch dafür, dass es sich für Euch lohnt.", sourceObjective = "Helft Greblin Flinkzünd nach unten.", completion = "Autsch... Mein Bein ist immer noch eingeschlafen. Tut das weh... Greblin Flinkzünd heiß ich, Archäologe bin ich.\n\nWie kann ich zu Diensten sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[35946] = { id = 35946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picker der Majestätische", description = "Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.\n\nIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.\n\nSeid Ihr damit einverstanden?", sourceObjective = "Nehmt den Blutschwur von Klingenmeisterin Na'Shra an.", sourceObjectiveStatus = "unverified-source-field" }
quests[35947] = { id = 35947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Giftes", description = "G.G.? Wir brauchen einen Namen und eine Ortsangabe. Keine verdammten Initialen.\n\n<Velonara holt eine kleine Phiole hervor.>\n\nDas ist mein letztes Fläschchen Foltergift. Wir benutzen es, um Gefangenen Informationen zu entlocken. Es ist... wirksam.\n\nBestreicht Eure Waffe damit und geht zum Lager der Zerschmetterten Hand ein Stück weiter. Verwickelt sie einfach in einen Kampf und verlangt Antworten... den Rest wird das Gift übernehmen. Ich habe genug von diesen Orcs.", sourceObjective = "Befragt Orcs der Zerschmetterten Hand in der Ausschlachterei und findet den Namen und den Aufenthaltsort von \"G.G.\" heraus.", completion = "Dieser Gardul Giftdolch ist so gut wie tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[35948] = { id = 35948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Gorenzahn", description = "Dieser Zahn ist ein Beweis für Eure Fähigkeit im Töten von Goren, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Zahn zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Wir sind beeindruckt von Eurer Fähigkeit, die Goren zu töten. Sie sind unerbittlich und unersättlich und können die Unvorbereiteten überwältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35950] = { id = 35950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Champions - Belohnungsquest" }
