quests[35958] = { id = 35958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisendocks - Belohnungsquest" }
quests[35959] = { id = 35959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Giftes", description = "G.G.? Wir brauchen 'nen ganzen Namen. Einen Ort!\n\nIch hab 'ne Idee, wie wir die erfahren können.\n\n<Hulda holt eine kleine Phiole hervor.>\n\nDas ist mein letztes Fläschchen Foltergift. Wir benutzen es, wenn wir Gefangenen Informationen entlock'n müssen.\n\nBestreicht Eure Waffe damit und geht ins Lager der Zerschmetterten Hand 'n Stück weiter. Verwickelt sie einfach in 'nen Kampf und verlangt Antworten... den Rest wird das Gift übernehmen.", sourceObjective = "Befragt Orcs der Zerschmetterten Hand in der Ausschlachterei und findet den Namen und den Aufenthaltsort von \"G.G.\" heraus.", completion = "Gardul Giftdolch, was? Der ist so gut wie tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[35960] = { id = 35960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun - Belohnungsquest" }
