quests[35969] = { id = 35969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 018 - Bündel eines Abenteurers" }
quests[35970] = { id = 35970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier wird Werterhaltung großgeschrieben!", description = "Ich bin auf der Suche nach wertvollen Artefakten. Die Art von Artefakten, die bei der Lösung der größten Mysterien Draenors helfen können und mit denen die Werterhaltungsgesellschaft des Dampfdruckkartells tonnenweise Kohle machen kann... und die Damen stehen auf Kohle, wenn Ihr wisst, was ich meine.\n\nAlso, Ihr besorgt mir die Artefakte, ich krieg die Damen und Ihr kriegt... Moment, was wolltet Ihr noch mal?", sourceObjective = "Besorgt eine Rotzahnkette, eine Kette aus violetten Zähnen und eine Ogerbüste.", progress = "Was habt Ihr gefunden? Irgendwas Lohnenswertes? Ähh... Bewahrenswertes?", completion = "Sehr schön! Was habt Ihr da?\n\nEine Halskette, nicht schlecht... noch eine Halskette, gut. Ein großer Stein in Form eines Ogerkopfes?\n\n<Greblin scheint verwirrt zu sein, er blickt zu Euch auf.>\n\nIm Ernst? Das ist ein Stein in Form eines Blödmanns. Na, was soll's, die Halsketten sehen gut aus.\n\nInsgesamt keine schlechte Ausbeute.", sourceObjectiveStatus = "unverified-source-field" }
quests[35971] = { id = 35971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 7" }
quests[35972] = { id = 35972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogeransturm", description = "Diese Oger stehen einer umfassenden Ausgrabung der Werterhaltungsgesellschaft des Dampfdruckkartells im Wege.\n\nSie sind brutale, gewalttätige, furchtbar stinkende Bestien. Und wenn ich ganz ehrlich bin, dann bin ich ziemlich sauer, dass sie meinen Gleiter kaputtgemacht haben.\n\nTut Ihr mir einen Gefallen? Entfernt sie vom Angesicht Draenors.\n\nDas macht allen das Leben leichter... Zumindest macht es mein Leben leichter.", sourceObjective = "Tötet 3 Oger und 3 Ogron.", completion = "Oh, das ist viel besser.\n\nVielleicht überlegen sie es sich das nächste Mal zweimal, bevor sie einen Stein nach jemandem werfen. Ähh... ich meine, wenn sie nicht so tot wären und so.", sourceObjectiveStatus = "unverified-source-field" }
quests[35973] = { id = 35973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brokyos Bestrafung", description = "Ich bin hier fast fertig, aber ich kann nicht guten Gewissens gehen.\n\nIch habe einen Ogron namens Brokyo gesehen, der einen unbezahlbaren Ring trägt. Unbezahlbar im Sinne von schweineteuer.\n\nNixxie befördert mich ganz bestimmt, wenn ich ihn ihr bringe.", sourceObjective = "Tötet Brokyo.", progress = "Habt Ihr Euch um Brokyo gekümmert?", completion = "Habt Ihr den Ring? Super! Damit wird die Werterhaltungsgesellschaft des Dampfdruckkartells gute Kohle machen.\n\nNixxie wird sich freuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35974] = { id = 35974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Nachtflutnest", description = "Die Eiserne Horde hat Goblins rekrutiert? Schaltet sie aus!", sourceObjective = "Verlangsamt die Eiserne Horde und sammelt Informationen über sie.", sourceObjectiveStatus = "unverified-source-field" }
